class Solution {
public:
    long long makeSubKSumEqual(std::vector<int>& arr, int k) {
        int n = arr.size();
        int g = std::gcd(n, k);
        long long ans = 0;
        for (int i = 0; i < g; ++i) {
            std::vector<int> group;
            for (int j = i; j < n; j += g) group.push_back(arr[j]);
            std::sort(group.begin(), group.end());
            int med = group[group.size() / 2];
            for (int x : group) ans += std::abs(x - med);
        }
        return ans;
    }
};

class Solution {
    public long makeSubKSumEqual(int[] arr, int k) {
        int n = arr.length;
        int g = gcd(n, k);
        long ans = 0;
        for (int i = 0; i < g; i++) {
            java.util.List<Integer> group = new java.util.ArrayList<>();
            for (int j = i; j < n; j += g) group.add(arr[j]);
            java.util.Collections.sort(group);
            int med = group.get(group.size() / 2);
            for (int x : group) ans += Math.abs((long) x - med);
        }
        return ans;
    }
    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

var makeSubKSumEqual = function(arr, k) {
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const n = arr.length;
    const g = gcd(n, k);
    let ans = 0;
    for (let i = 0; i < g; i++) {
        const group = [];
        for (let j = i; j < n; j += g) group.push(arr[j]);
        group.sort((a, b) => a - b);
        const med = group[Math.floor(group.length / 2)];
        for (const x of group) ans += Math.abs(x - med);
    }
    return ans;
};
